import dotenv from 'dotenv';
dotenv.config();
process.env.ENABLE_DB = 'true';

import { getPrisma } from '../src/lib/db/client';

async function main() {
  const prisma = getPrisma();
  if (!prisma) {
    throw new Error('Database not configured');
  }

  const story = await prisma.story.findUnique({
    where: { id: 'story_mt4ofllt' },
  });

  if (!story) {
    throw new Error('Story story_mt4ofllt not found');
  }

  const manifest = story.manifest as any;

  // 1. Update initial scene ID
  manifest.initialSceneId = 'scene_hiram_trail_01';

  // 2. Update initial story beat (Prologue on the Hiram Trail)
  manifest.initialStoryBeats = [
    {
      sceneId: 'scene_hiram_trail_01',
      chapterId: 'act_mtw24uoe_q9q4',
      locationId: 'loc_muzo9ij9_ycy6',
      choices: [],
      narrativeText:
        "سپیدهدم بر فراز بادیهٔ هیرام شکافته میشود و نوار باریکی از روشنایی زرین و گلگون بر پهنهٔ تپهماهورهای خشک، صخرههای بادخورده و بوتههای تنک خاربُن دامن میگسترد. بادی سرد و گزنده از کوهسار باختر بر خاک بیابان میوزد و غبار کورهراه را تا ساق پا برمیانگیزد.\n\nپیش رویت، در میان غبار سحرگاهی دشت، صف طویل کاروان شترهای سرخموی هیرام به راه افتاده است. درایهای برنزی که از گردن شتران پیشاهنگ آویختهاند، همآهنگ با گامهای سنگین و خستگیناپذیر چهارپایان، طنینی بم و یکنواخت در فضای دشت میپراکنند؛ آوایی که قرنهاست در این دیار بیآبوعلف، نشان از حیات دارد. بوی خاکِ نمکشیده از شبنم سحر، پشم نمدار شتران، تسمههای چربشدهٔ بار و دود خاکستریِ آخرین خارهای نیمسوز در آتشگاه شبانه، مشام را پر میکند.\n\nپیشاپیش کاروان، کاروانسالار «برزو سنگتراش» گام برمیدارد؛ مردی بلندبالا و چهارشانه با بازوانی ستبر و پشتی اندکی خمیده که یادگار سالها کوبیدن پتک بر تختهسنگهای کوهستان است. آفتاب بیرحم کویر، چهرهاش را چون چرم کهنه تیره و پرشیار ساخته و خطوط عمیقی از خشم و تجربه بر پیشانی و کنج چشمان کهرباییاش نشانده است. ریش زبر و جوگندمیاش در غبار بیابان به خاکستری میزند. ردایی بلند و سنگین از پشم دستبافِ تیره بر تن دارد که تا قوزک پایش میرسد و شال پهن نمدی به رنگ خرمایی بر کمر بسته است؛ شالی که غلاف چرمیِ دشنهای کهنه و ریسمان شاقول از آن آویزان است. او با دستانی پهن و انگشتانی استخوانی و پینهبسته، مهار بافتهٔ شتر پیشرو را در چنگ میفشارد و در حالی که با نگاهی باریک و شکاک خط ستیغ تپهها را میپاید، زیر لب با صدایی بم و زنگدار بر ساربانان نهیب میزند:\n«پایینِ دره هنوز بادِ سرخ نخوابیده! پا سست نکنید... تا آفتاب به کمرکش آسمون نرسیده، باید به رباطِ سرخ نزدیک شده باشیم. این بادیه با کسی که لفتش بده شوخی نداره!»\n\nکمی عقبتر، «بهرام دشتبان» در حرکت است؛ مردی ترکهای و بلندقامت با گامهایی کشیده و نرم که ویژهٔ ساربانان بیابانگرد است. جلیقهای بیدکمه از پوست گوسفند با پشمهای ساییدهشده بر روی پیراهن کرباس و نخنمای سرمهایاش به تن دارد که گرد راههای دور بر آن نشسته است. مچبندهایی چرمی، سیاهشده از عرق و پیه، بر ساعد بسته و چوبدستی بلند و گرهداری از چوب ارژن در مشت میفشارد. بینی کشیده و اندکی شکستهاش در کنار چشمانی سیاه، براق و تیزبین، به سیمایش هیبت شاهینهای بیابان را بخشیده است. او همگام با کاروان، با نگاهی تیز نحوهٔ فرود آمدن پینههای گوشتی پای شتران را بر زمین میسنجد تا مبادا چهارپایی بلنگد یا برمد.\n\nدر میانهٔ صفوف، «مازیار مشکدار» در تکاپوست؛ مردی کوتاهقامتتر از دیگران، اما با تنهای توپر، گردنی کلفت و عضلانی، و پاهایی ورزیده در چکمههای چرمی بیپاشنهای که به خاک بادیه آغشتهاند. سر و صورتش را در دستاری نیلیرنگ پیچیده و تنها لبهای خشکیده و آفتابسوختهاش از زیر آن پیداست؛ لبهایی که طرح لبخندی کنایهآمیز هرگز از آنها جدا نمیشود. حمایلی پهن و چرمی به شکل ضربدری بر سینهٔ فراخش نشسته که پیمانههای مسیِ فرورفته و درفشهای مشکدوزی از حلقههای برنجی آن آویزاناند. سه مشک بزرگ از پوست بز بر جهاز شترِ کناریاش تاب میخورند و او با دستانی خنک و خیس از آب چاه، پیدرپی کام تشنهٔ مسافران را با جرعهای گوارا تر میکند؛ در همان حال که ساربانان هیرام با زمزمههای بم و کشدارِ حدیخوانی، کاروان را در شیار جاده پیش میرانند.\n\nافق دشت هیرام پیش رویت گشوده است؛ فرسنگها راه در دل بیابان تا رسیدن به رباط سرخ، و سرانجام سرازیر شدن به درهٔ «زروانرود» و باراندازهای پررونق «زرینپل». گزندهای راه—از طوفانهای ریگ و جانوران زهرآگین بیابان تا شیبهای سنگلاخی—همچنان در کمیناند، اما کاروان اینک در پناه هوشیاری همراهانش به دل جاده زده است.",
    },
  ];

  // 3. Update Saga Chapter 1 (Arc 1: The Caravan in the Hiram Wilderness)
  const chapters = manifest.saga?.chapters || [];
  const arc1Index = chapters.findIndex((c: any) => c.id === 'act_mtw24uoe_q9q4' || c.chapterNumber === 1);

  const updatedArc1 = {
    id: 'act_mtw24uoe_q9q4',
    chapterNumber: 1,
    title: 'پرده ۱: کاروان در بادیهٔ هیرام',
    scopeTier: 'wilderness',
    narrativeGoal:
      'همراهی و هدایت کاروان در گسترهٔ خشک و ناهموار دشت هیرام، رویارویی با خطرات جاده و پدیده‌های کویر (طوفان‌های سرخ، جانوران بادیه، کمبود آب و انتخاب معابر)، پشت سر گذاشتن ایستگاه‌های بین‌راهی (رباط سرخ)، و رساندن کاروان به سلامت به بارانداز کاروانسرای شاخ زرین و دروازه‌های گشودهٔ زرین‌پل.',
    completionSummaryPrompt:
      'پایان موفقیت‌آمیز گذر از بادیهٔ هیرام و رسیدن کاروان به کاروانسرای شاخ زرین در کرانهٔ زروان‌رود با دروازه‌های باز شهر.',
    prerequisiteFlags: [],
    scenes: [],
    stages: [
      {
        id: 'stage_mtxbgel0_d0cc',
        order: 1,
        stageType: 'inciting_incident',
        title: 'آغاز سفر — حرکت از چاه سنگ به دل بادیه',
        description:
          'کاروان شترهای سرخ و مسافران، اتراق‌گاه چاه سنگ را ترک کرده و پا به پهنهٔ گسترده و بادگیر دشت هیرام می‌گذارند. آشنایی با همراهان، بررسی توشه و سلاح‌ها، و قرار گرفتن در صف پیش‌قراولان یا حامیان کاروان در نخستین فرسنگ‌های راه.',
      },
      {
        id: 'stage_mtxbgel0_5knz',
        order: 2,
        stageType: 'rising_action',
        title: 'آزمون‌های راه — دشت‌های بی‌حاصل و اتراق در رباط سرخ',
        description:
          'پیشروی در خاک‌های فرسایندهٔ هیرام و مواجهه با پدیده‌های بیابان (ردپای جانوران درنده و گزندگان کویر، طوفان‌های غبار سرخ، یا عارضه‌های زمین‌شناسی)، رسیدن به آب‌انبار خشتی رباط سرخ برای توقف، آب‌گیری، تبادل اخبار و حل تنش‌های میان مسافران.',
      },
      {
        id: 'stage_mtxbgel0_sm3g',
        order: 3,
        stageType: 'climax',
        title: 'گذرگاه پرمخاطره — پشته‌های باختری و آزمون نهایی بادیه',
        description:
          'گذر از دشوارترین بخش مسیر در شیب‌ها و پشته‌های ناهموار غربی هیرام پیش از سرازیر شدن به درهٔ زروان‌رود؛ تصمیم‌گیری دربارهٔ مسیرهای میان‌بر یا امن، نجات کاروان از رانش ریگ یا درندگان شب، و اثبات شایستگی به عنوان حافظ و راهنمای کاروان.',
      },
      {
        id: 'stage_mtxbgel0_n913',
        order: 4,
        stageType: 'resolution',
        title: 'پایان بادیه — فرود به درهٔ زروان‌رود و بارانداز شاخ زرین',
        description:
          'افق کویر جای خود را به درهٔ رودخانه می‌دهد. پهنهٔ پرآب زروان‌رود و هیبت سنگی زرین‌پل در افق پدیدار می‌شود. کاروان با بارهای سالم وارد محوطهٔ باز کاروانسرای شاخ زرین می‌شود؛ دروازه‌های شهر باز و شرایط عادی است و راه برای ورود به بازارچه و ماجراهای درون شهر گشوده می‌گردد.',
      },
    ],
  };

  if (arc1Index >= 0) {
    chapters[arc1Index] = updatedArc1;
  } else {
    chapters.unshift(updatedArc1);
  }

  manifest.saga = {
    ...(manifest.saga || {}),
    chapters,
  };

  // 4. Ensure trade routes point to the appropriate origin and destinations
  if (Array.isArray(manifest.worldBible?.tradeRoutes)) {
    const mainCaravan = manifest.worldBible.tradeRoutes.find((r: any) => r.id === 'route_mv00dghz_fosto');
    if (mainCaravan) {
      mainCaravan.originLocationId = 'loc_muzo9ij9_ycy6';
      mainCaravan.destinationLocationId = 'loc_mtr2c3uu_yocj';
    }
  }

  // 5. Save updated manifest to Prisma database
  await prisma.story.update({
    where: { id: 'story_mt4ofllt' },
    data: {
      manifest,
    },
  });

  console.log('✅ Arc 1 and Opening Scene successfully updated for story_mt4ofllt!');
  console.log('InitialSceneId:', manifest.initialSceneId);
  console.log('InitialBeat locationId:', manifest.initialStoryBeats[0].locationId);
  console.log('Chapter 1 title:', manifest.saga.chapters[0].title);
  console.log('Chapter 1 scope:', manifest.saga.chapters[0].scopeTier);
  console.log('Stages count:', manifest.saga.chapters[0].stages.length);
}

main()
  .catch(console.error)
  .finally(() => process.exit(0));
